/**
 * Questions in a split or as cards. Axes: layout (head: the heading and an action beside the disclosures, aside:
 * the disclosures beside a help card, media: the disclosures and an action beside a picture, search: a finder
 * beside a picture, cards: the questions as cards), cards (grid3, grid4, icons), mediaSide, tone.
 */
import { type ReactNode } from "react";
import { Box } from "../primitives/box/box";
import { Button } from "../primitives/button/button";
import { FaqCards } from "../components/faq-cards";
import { FaqDisclosures } from "../components/faq-disclosures";
import { FaqFinder } from "../components/faq-finder";
import { FaqHelp } from "../components/faq-help";
import { MediaFrame } from "../components/media-frame";
import { SectionFrame } from "../components/section-frame";
import { tpl } from "../utils";
import type { Question, FaqSplitLabels } from "./faq-split.types";
import type { Feature } from "./feature-grid.types";
import type { FaqTab } from "./faq-list.types";

export type FaqSplitProps = {
  id: string;
  title: string;
  lead?: string;
  badge?: string;
  items: Question[];
  channels: Feature[];
  topics: FaqTab[];
  labels: FaqSplitLabels;
  layout?: "head" | "aside" | "media" | "search" | "cards";
  cards?: "grid3" | "grid4" | "icons";
  mediaSide?: "end" | "start";
  tone?: "default" | "muted";
};

export function FaqSplit({
  id,
  title,
  lead = "",
  badge = "",
  items,
  channels,
  topics,
  labels,
  layout = "head",
  cards = "grid3",
  mediaSide = "end",
  tone = "default",
}: FaqSplitProps) {
  return (
    <>
      {((layout as string) === "cards") ? (
        <SectionFrame id={id} title={title} lead={lead} heading={{ badge }} tone={tone} density="default">
          <FaqCards items={items} labels={labels} cards={cards} />
        </SectionFrame>
      ) : null}
      {((layout as string) === "head") ? (
        <SectionFrame
          id={id}
          title={title}
          lead={lead}
          heading={{ badge }}
          tone={tone}
          density="default"
          layout="split"
          media={{ show: true, side: "end", align: "start" }}
          aside={(
            <FaqDisclosures items={items} name={tpl("{0}-faq", id)} />
          )}
        >
          <Box>
            <Button variant="default" size="default" href="#/contact" data-testid="faq-cta">
              {labels.cta}
            </Button>
          </Box>
        </SectionFrame>
      ) : null}
      {((layout as string) === "aside") ? (
        <SectionFrame
          id={id}
          title={title}
          lead={lead}
          heading={{ badge }}
          tone={tone}
          density="default"
          layout="split"
          media={{ show: true, side: "end", align: "start" }}
          aside={(
            <FaqHelp labels={labels} channels={channels} />
          )}
        >
          <FaqDisclosures items={items} name={tpl("{0}-faq", id)} />
        </SectionFrame>
      ) : null}
      {((layout as string) === "media") ? (
        <SectionFrame
          id={id}
          title={title}
          lead={lead}
          heading={{ badge }}
          tone={tone}
          density="default"
          layout="split"
          media={{ show: true, side: mediaSide, align: "start" }}
          aside={(
            <MediaFrame alt={title} ratio="4/3" />
          )}
        >
          <FaqDisclosures items={items} name={tpl("{0}-faq", id)} />
          <Box>
            <Button variant="default" size="default" href="#/contact" data-testid="faq-cta">
              {labels.cta}
            </Button>
          </Box>
        </SectionFrame>
      ) : null}
      {((layout as string) === "search") ? (
        <SectionFrame
          id={id}
          title={title}
          lead={lead}
          heading={{ badge }}
          tone={tone}
          density="default"
          layout="split"
          media={{ show: true, side: mediaSide }}
          aside={(
            <MediaFrame alt={title} ratio="4/3" />
          )}
        >
          <FaqFinder items={items} labels={labels} topics={topics} />
        </SectionFrame>
      ) : null}
    </>
  );
}

