export type Question = {
  id: string;
  question: string;
  answer: string;
  category: string;
  icon: string;
};

export type FaqSplitLabels = {
  cta: string;
  more: string;
  asideTitle: string;
  asideText: string;
  asideCta: string;
  search: string;
  popular: string;
  query?: string;
};
